INSERT INTO public.products (name, description, price, image_url, category_slug, stock, is_active, is_popular, allergens, storage_method, shelf_life) VALUES
  ('무지개 돌잔치 10종', '무지개 색상의 열 가지 화과자. 대규모 돌잔치에 적합한 넉넉한 구성입니다.', 78000, 'https://picsum.photos/seed/wagashi9/600/600', 'dol', 20, true, false, '찹쌀가루, 백앙금, 과일분말, 천연색소', '냉장', '제조일로부터 5일'),
  ('화촉 웨딩 화과자', '촛불처럼 은은한 아름다움을 담은 웨딩 화과자. 하객들에게 잊지 못할 답례품을 선물하세요.', 72000, 'https://picsum.photos/seed/wagashi10/600/600', 'wedding', 22, true, true, '백앙금, 장미시럽, 한천, 천연색소', '냉장', '제조일로부터 5일'),
  ('더블 하트 웨딩 세트', '두 개의 하트가 만나는 모양. 사랑하는 두 사람의 결합을 상징하는 아름다운 세트입니다.', 58000, 'https://picsum.photos/seed/wagashi11/600/600', 'wedding', 16, true, false, '찹쌀가루, 백앙금, 딸기, 천연색소', '냉장', '제조일로부터 5일'),
  ('축복 웨딩 답례품 50개', '50개입 웨딩 답례용 미니 화과자. 하객 한 분 한 분께 감사를 전하세요.', 180000, 'https://picsum.photos/seed/wagashi12/600/600', 'wedding', 5, true, false, '찹쌀가루, 팥앙금, 백앙금, 천연색소', '냉장', '제조일로부터 5일'),
  ('추석 한가위 세트', '풍성한 한가위를 위한 전통 화과자 세트. 송편 모양과 보름달을 담아 명절의 정취를 전합니다.', 68000, 'https://picsum.photos/seed/wagashi13/600/600', 'holiday', 35, true, true, '찹쌀가루, 팥앙금, 송편소, 천연색소', '냉장', '제조일로부터 5일'),
  ('설날 복주머니 화과자', '복을 담은 주머니 모양의 화과자. 새해 첫 선물로 사랑하는 사람에게 행운을 전하세요.', 52000, 'https://picsum.photos/seed/wagashi14/600/600', 'holiday', 28, true, false, '백앙금, 계피, 대추, 천연색소', '냉장', '제조일로부터 5일'),
  ('제사 정성 5종 세트', '정성을 담아 준비하는 제사상 화과자. 전통 방식으로 하나하나 수작업 제작합니다.', 45000, 'https://picsum.photos/seed/wagashi15/600/600', 'holiday', 40, true, false, '찹쌀가루, 팥앙금, 한천', '냉장', '제조일로부터 5일'),
  ('기업 로고 각인 세트', '회사 로고를 각인한 맞춤형 화과자. 비즈니스 선물이나 기업 행사에 적합합니다.', 95000, 'https://picsum.photos/seed/wagashi16/600/600', 'corporate', 50, true, true, '찹쌀가루, 백앙금, 천연색소', '냉장', '제조일로부터 5일');
